     * How much of a dimension's usage the customer actually owes for over the
     * invoiced period.
     *
     * An allowance the usage never exhausted, an allowance without a limit, and
     * a plan that does not permit going past the allowance all leave nothing to
     * charge for. Where the plan does permit it, only the usage past a finite
     * allowance is owed for. A dimension carrying no allowance is owed for in
     * full.
     */
    static owedQuantity({
        total,
        dimension,
    }: {
        total: number;
        dimension: Pick<ReadDimensionResponseData, 'usageEntitlement' | 'overageAllowed'>;
    }): number {
        const usageTotal = Number(total);
        const owed = Number.isFinite(usageTotal) ? usageTotal : 0;
        const entitlement = dimension?.usageEntitlement;
        if (entitlement === undefined || entitlement === null) {
            // Nothing is included with the plan, so all of the usage is owed for.
            return owed;
        }
        if (entitlement === 'inf') {
            // The allowance can never be exhausted, so nothing is ever owed.
            return 0;
        }
        const allowance = typeof entitlement === 'number' ? entitlement : parseFloat(entitlement);
        if (!Number.isFinite(allowance)) {
            return owed;
        }
        if (dimension?.overageAllowed !== overageAllowedEnum.true) {
            // The plan does not permit usage past the allowance to be charged for.
            return 0;
        }
        const beyondAllowance = owed - allowance;
        return beyondAllowance > 0 ? beyondAllowance : 0;
    }

